package com.opensocket.aievent.core.issuetracking.change;
import java.time.OffsetDateTime; import java.util.Objects;
public record ExternalRelationSync(String tenantId,String syncId,String connectionId,String projectMappingId,String externalProjectId,String sourceExternalIssueId,String targetExternalIssueId,String sourceTaskIssueLinkId,String targetTaskIssueLinkId,String relationType,ExternalSyncDirection direction,String sourceMarker,String providerRelationId,ExternalSyncStatus status,int retryCount,String lastErrorCode,String lastErrorMessage,long version,OffsetDateTime createdAt,OffsetDateTime updatedAt,String correlationId) {
 public ExternalRelationSync { tenantId=req(tenantId,"tenantId");syncId=req(syncId,"syncId");connectionId=req(connectionId,"connectionId");projectMappingId=norm(projectMappingId);externalProjectId=norm(externalProjectId);sourceExternalIssueId=req(sourceExternalIssueId,"sourceExternalIssueId");targetExternalIssueId=req(targetExternalIssueId,"targetExternalIssueId");sourceTaskIssueLinkId=norm(sourceTaskIssueLinkId);targetTaskIssueLinkId=norm(targetTaskIssueLinkId);relationType=req(relationType,"relationType");direction=Objects.requireNonNull(direction,"direction is required");sourceMarker=req(sourceMarker,"sourceMarker");providerRelationId=norm(providerRelationId);status=Objects.requireNonNull(status,"status is required");if(retryCount<0)throw new IllegalArgumentException("retryCount cannot be negative");if(version<1)throw new IllegalArgumentException("version must be positive");createdAt=Objects.requireNonNull(createdAt,"createdAt is required");updatedAt=Objects.requireNonNull(updatedAt,"updatedAt is required");correlationId=norm(correlationId);lastErrorCode=norm(lastErrorCode);lastErrorMessage=norm(lastErrorMessage); }
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
